-- GenDB engine variant Q20-commuted_comparisons: template q20.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  s_name,
  s_address
FROM supplier, nation
WHERE
  s_suppkey IN (
    SELECT
      ps_suppkey
    FROM partsupp
    WHERE
      ps_partkey IN (
        SELECT
          p_partkey
        FROM part
        WHERE
          p_name LIKE $1
      )
      AND (
        SELECT
          0.5 * SUM(l_quantity)
        FROM lineitem
        WHERE
          ps_partkey = l_partkey
          AND ps_suppkey = l_suppkey
          AND $2 <= l_shipdate
          AND $2 + INTERVAL '1 YEAR' > l_shipdate
      ) < ps_availqty
  )
  AND n_nationkey = s_nationkey
  AND $3 = n_name
ORDER BY
  s_name
